import { createSlice, PayloadAction } from '@reduxjs/toolkit';

import { type AdvCampaignRead } from 'entities/Brand';

interface IBrandSlice {
	advCampaign: AdvCampaignRead | null;
	isOpenCreateAutomationDrawer: boolean;
	isOpenDetailsPopup: boolean;
	isOpenSaveToAutomationsDrawer: boolean;
	visitedAdvCampaigns: string[];
}

const initialState: IBrandSlice = {
	advCampaign: null,
	isOpenCreateAutomationDrawer: false,
	isOpenDetailsPopup: false,
	isOpenSaveToAutomationsDrawer: false,
	visitedAdvCampaigns: [],
};

export const brandSlice = createSlice({
	name: 'brand',
	initialState,
	reducers: {
		setAdvCampaign: (state, action: PayloadAction<AdvCampaignRead | null>) => {
			state.advCampaign = action.payload;
		},
		setIsOpenSaveToAutomationsDrawer: (state, action: PayloadAction<boolean>) => {
			state.isOpenSaveToAutomationsDrawer = action.payload;
			if (!action.payload) {
				state.isOpenDetailsPopup = false;
				state.advCampaign = null;
			}
		},
		setIsOpenCreateAutomationDrawer: (state, action: PayloadAction<boolean>) => {
			state.isOpenCreateAutomationDrawer = action.payload;
			if (!action.payload) {
				state.isOpenSaveToAutomationsDrawer = false;
				state.isOpenDetailsPopup = false;
				state.advCampaign = null;
			}
		},
		setIsOpenDetailsPopup: (state, action: PayloadAction<boolean>) => {
			state.isOpenDetailsPopup = action.payload;
			if (!action.payload) {
				state.advCampaign = null;
			}
		},
		setVisitedAdvCampaign: (state, action: PayloadAction<string>) => {
			state.visitedAdvCampaigns = state.visitedAdvCampaigns.concat(action.payload);
		},
	},
});

export default brandSlice.reducer;

export const {
	setAdvCampaign,
	setIsOpenCreateAutomationDrawer,
	setIsOpenDetailsPopup,
	setIsOpenSaveToAutomationsDrawer,
	setVisitedAdvCampaign,
} = brandSlice.actions;
