import { FC } from 'react';

import { Flex, FlexProps, Switch, Typography } from 'antd';

interface ISwitchWithTextProps extends FlexProps {
	subTitle?: string;
	isChecked: boolean;
	onSwitchChange: (val: boolean) => void;
}

export const SwitchWithText: FC<ISwitchWithTextProps> = ({
	className,
	isChecked,
	subTitle,
	children,
	onSwitchChange,
	...props
}) => {
	return (
		<Flex gap={12} justify="space-between" className={className} {...props}>
			<Flex vertical gap={4}>
				<Typography.Text>{children}</Typography.Text>
				{!!subTitle && <Typography.Text type="secondary">{subTitle}</Typography.Text>}
			</Flex>
			<Switch onChange={onSwitchChange} checked={isChecked} />
		</Flex>
	);
};
