import { FC, HTMLAttributes, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Flex } from 'antd';

import settingsImage from 'assets/images/titles/settings.webp';
import {
	AccountSettings,
	SettingsAbout,
	// SettingsContent,
	SettingsNotifications,
	useAccountSettingsPartialUpdateMutation,
	useAccountSettingsRetrieveQuery,
} from 'entities/User';
import { useBackButton } from 'shared/hooks';
import { EMainRoutes } from 'shared/typings';
import { Content, OverlayLoader, Page, PageTitle } from 'shared/ui';

interface ISettingsProps extends HTMLAttributes<HTMLDivElement> {}

export const Settings: FC<ISettingsProps> = ({ ...props }) => {
	const { t } = useTranslation();
	useBackButton(`${EMainRoutes.DASHBOARD}`);
	const [accountSettings, setAccountSettings] = useState<AccountSettings>();
	const { data, isFetching: isAccountSettingsLoading } = useAccountSettingsRetrieveQuery();
	const [accountSettingsPartialUpdate, { isLoading }] = useAccountSettingsPartialUpdateMutation();

	const partialUpdate = (key: string, value: boolean | string) => {
		setAccountSettings({
			...data,
			[key]: value,
		});
		accountSettingsPartialUpdate({ [key]: value });
	};

	useEffect(() => {
		setAccountSettings(data);
	}, [data]);

	return (
		<Page {...props}>
			{(isLoading || isAccountSettingsLoading) && <OverlayLoader />}
			<PageTitle
				image={<img src={settingsImage} height={80} width={80} alt="profile" />}
				subtitle={t('Здесь можно изменить предпочтения и управлять уведомлениями')}>
				{t('Настройки')}
			</PageTitle>
			<Content>
				<Flex vertical gap={8}>
					<SettingsNotifications accountSettings={accountSettings} partialUpdate={partialUpdate} />
					{/*<SettingsContent accountSettings={accountSettings} partialUpdate={partialUpdate} />*/}
					<SettingsAbout />
					{/*TODO:*/}
					<Button danger size="small" type="text" onClick={() => console.log('Удалить аккаунт')}>
						{t('Удалить аккаунт')}
					</Button>
				</Flex>
			</Content>
		</Page>
	);
};

export default Settings;
