import { Dispatch, FC, SetStateAction, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';

import { Badge, type BadgeProps, Button, Flex, Modal, type ModalProps, Typography } from 'antd';

import CalendarIcon from 'assets/images/icons/calendar-with-clock.svg?react';
import EyeIcon from 'assets/images/icons/eye.svg?react';
import { i18n } from 'i18n';
import { EMainRoutes, EYmPageScreen } from 'shared/typings';
import { sendYmEvent } from 'shared/utils';

const contentMap = {
	instant: {
		title: i18n.t('Пост опубликован'),
		text: i18n.t('Публикация была учтена в планнере'),
		btnText: i18n.t('Показать в канале'),
		btnIcon: <EyeIcon />,
		status: 'success' as BadgeProps['status'],
		goTo: '/', //TODO:
		ymEvent: null,
	},
	regular: {
		title: i18n.t('Пост запланирован'),
		text: i18n.t('Отредактировать или отменить публикацию можно в планнере'),
		btnText: i18n.t('Показать в планнере'),
		btnIcon: <CalendarIcon />,
		status: 'processing' as BadgeProps['status'],
		goTo: `/${EMainRoutes.PLANNER}`,
		ymEvent: 'click_show_in_scheduler',
	},
};

interface ISuccessPopupProps extends ModalProps {
	postType: 'instant' | 'regular';
	publishedAt: string | undefined;
	setIsSuccessModalOpen: Dispatch<SetStateAction<boolean>>;
}

export const SuccessPopup: FC<ISuccessPopupProps> = ({
	postType = 'instant',
	publishedAt,
	setIsSuccessModalOpen,
	...props
}) => {
	const { t } = useTranslation();
	const navigate = useNavigate();

	const handleCloseClick = () => {
		setIsSuccessModalOpen(false);
		navigate(-1);
	};

	const handleGoToClick = () => {
		contentMap[postType].ymEvent && sendYmEvent(contentMap[postType].ymEvent, { page_screen: EYmPageScreen.POPUP });
		setIsSuccessModalOpen(false);
		navigate(contentMap[postType].goTo);
	};

	useEffect(() => {
		contentMap.regular.goTo = `/${EMainRoutes.PLANNER}?plannerDate=${publishedAt}&plannerType=day`;
	}, [publishedAt]);

	return (
		<Modal
			title={
				<>
					<Badge status={contentMap[postType].status} /> {contentMap[postType].title}
				</>
			}
			destroyOnHidden
			footer={
				<Flex gap={8} justify="space-between">
					<Button
						type="primary"
						size="large"
						icon={contentMap[postType].btnIcon}
						htmlType="button"
						onClick={handleGoToClick}>
						{contentMap[postType].btnText}
					</Button>
					<Button size="large" htmlType="button" onClick={handleCloseClick}>
						{t('Закрыть')}
					</Button>
				</Flex>
			}
			onCancel={handleCloseClick}
			{...props}>
			<Typography.Paragraph>{contentMap[postType].text}</Typography.Paragraph>
		</Modal>
	);
};
