import { Dispatch, FC, SetStateAction, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Flex } from 'antd';
import { UploadFile } from 'antd/es/upload/interface';
import { useFormik } from 'formik';
import * as Yup from 'yup';

import CalendarIcon from 'assets/images/icons/calendar.svg?react';
import LightningIcon from 'assets/images/icons/lightning.svg?react';
import { type AdvCampaignRead } from 'entities/Brand';
import { EditPostPageState, IPostFormState, usePostSlice } from 'entities/Post';
import { AutoDeletionAfterEnum, usePlannerPostsCreateMutation } from 'features/Planner';
import { EMainRoutes, EYmPageScreen } from 'shared/typings';
import { BottomPanel, ButtonStyleLink } from 'shared/ui';
import { sendYmEvent } from 'shared/utils';

import { PostEditorPart } from './PostEditorForm/PostEditorPart';
import styles from './PostForm.module.scss';
import { PublishingSettingsPart } from './PublishingSettingsPart/PublishingSettingsPart';
import { SuccessPopup } from './SuccessPopup/SuccessPopup';

interface IPostFormProps {
	advCampaign: AdvCampaignRead;
	pageState: EditPostPageState;
	setPageState: Dispatch<SetStateAction<EditPostPageState>>;
}

export const PostForm: FC<IPostFormProps> = ({ advCampaign, pageState, setPageState }) => {
	const { t } = useTranslation();

	const [editingTime, setEditingTime] = useState<Date | null>(null);
	const [isSuccessModalOpen, setIsSuccessModalOpen] = useState<boolean>(false);
	const { formState, setFormState } = usePostSlice();

	const initialState: IPostFormState = {
		channel_ids: formState?.channel_ids || null,
		date: formState?.date || null,
		time: formState?.time || null,
		auto_deletion_after: formState?.auto_deletion_after || AutoDeletionAfterEnum.Never,
		content: formState?.content || advCampaign?.posts[0]?.content,
		publishNow: formState?.publishNow || false,
		images: formState?.images || null,
	};

	const [createPost, { isLoading, isSuccess, reset, data }] = usePlannerPostsCreateMutation();

	const { handleSubmit, setFieldValue, values, isValid, dirty } = useFormik({
		initialValues: initialState,
		validationSchema: Yup.object({
			channel_ids: Yup.string().required(t('Это поле обязательно для заполнения')),
			content: Yup.string().max(8192),
			publishNow: Yup.boolean(),
			date: Yup.string().when('publishNow', ([publishNow], schema) => {
				return publishNow ? schema.notRequired() : schema.required();
			}),
		}),
		onSubmit: (value) => {
			sendYmEvent(values.publishNow ? 'click_publish' : 'click_schedule', {
				page_screen: EYmPageScreen.CREATE_POST_SCREEN,
			});
			reset();
			const formData = new FormData();

			const publishedAt =
				!value.publishNow &&
				value.date
					?.set('hour', value.time?.hour() || 0)
					.set('minute', value.time?.minute() || 0)
					.toISOString();

			formData.append('post_id', advCampaign.posts[0].uuid || '');
			formData.append('channel_ids', value.channel_ids || '');
			formData.append('auto_deletion_after', value.auto_deletion_after);
			value.content && formData.append('content', value.content);
			publishedAt && formData.append('published_at', publishedAt);
			value.images?.length &&
				value.images.forEach((image: UploadFile) => formData.append('images', image.originFileObj || ''));

			createPost(formData);
		},
	});

	const handleBackClick = () => {
		// setFieldValue('content', advCampaign?.posts[0]?.content);
		setPageState(EditPostPageState.PUBLISHING_SETTINGS);
	};

	const handleSaveClick = () => {
		setEditingTime(new Date());
		setPageState(EditPostPageState.PUBLISHING_SETTINGS);
	};

	useEffect(() => {
		if (isSuccess) {
			setIsSuccessModalOpen(true);
		}
	}, [isSuccess]);

	useEffect(() => {
		return () => {
			setFormState(null);
		};
	}, []); //eslint-disable-line react-hooks/exhaustive-deps

	return (
		<>
			{pageState === EditPostPageState.PUBLISHING_SETTINGS && (
				<>
					<PublishingSettingsPart
						editingTime={editingTime}
						setPageState={setPageState}
						setFieldValue={setFieldValue}
						values={values}
					/>

					<BottomPanel>
						<Flex justify={'space-between'} gap={8} className={styles.postForm__footer}>
							{/*TODO: to */}
							<ButtonStyleLink size="large" to={`/${EMainRoutes.CATALOG}`}>
								{t('Назад')}
							</ButtonStyleLink>
							<Button
								disabled={!isValid || !dirty}
								loading={isLoading}
								size="large"
								type="primary"
								icon={values.publishNow ? <LightningIcon /> : <CalendarIcon />}
								onClick={() => handleSubmit()}>
								{values.publishNow ? t('Опубликовать') : t('Запланировать')}
							</Button>
						</Flex>
					</BottomPanel>
				</>
			)}
			{pageState === EditPostPageState.POST_EDITOR && (
				<>
					<PostEditorPart values={values} setFieldValue={setFieldValue} advCampaign={advCampaign} />
					<Flex justify="space-between" gap={8} className={styles.postForm__footer}>
						<Button htmlType="button" size="large" onClick={handleBackClick}>
							{t('Назад')}
						</Button>
						<Button htmlType="button" size="large" type="primary" onClick={handleSaveClick}>
							{t('Сохранить')}
						</Button>
					</Flex>
				</>
			)}

			{isSuccessModalOpen && (
				<SuccessPopup
					postType={values.publishNow ? 'instant' : 'regular'}
					open={isSuccessModalOpen}
					setIsSuccessModalOpen={setIsSuccessModalOpen}
					publishedAt={data?.published_at}
				/>
			)}
		</>
	);
};
