import { FC } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, Typography } from 'antd';

import { AccountSettings, BotPostSendTimeEnum, IProfileItem, ProfileItem } from 'entities/User';
import { i18n } from 'i18n';
import { SwitchWithText } from 'shared/ui';

import styles from './SettingsNotifications.module.scss';

const sendTimeOption: { [key in BotPostSendTimeEnum]: string } = {
	[BotPostSendTimeEnum.$10]: i18n.t('За 10 минут'),
	[BotPostSendTimeEnum.$30]: i18n.t('За полчаса'),
	[BotPostSendTimeEnum.$60]: i18n.t('За час'),
};

interface ISettingsNotificationsProps {
	accountSettings: AccountSettings | undefined;
	partialUpdate: (key: string, value: boolean | string) => void;
}

export const SettingsNotifications: FC<ISettingsNotificationsProps> = ({ accountSettings, partialUpdate }) => {
	const { t } = useTranslation();

	const botPostArray: Array<IProfileItem> = [
		{
			title: t('Присылать'),
			key: 'publish_bot_post_send',
			value: 'before_publication',
			isDisabled: true,
			type: 'select',
			items: [{ label: 'Перед публикацией', value: 'before_publication' }],
		},
		{
			title: t('Время'),
			key: 'bot_post_send_time',
			value: accountSettings?.bot_post_send_time ? sendTimeOption[accountSettings.bot_post_send_time] : '',
			isDisabled: !accountSettings?.bot_allow_send_post,
			type: 'select',
			items: Object.entries(sendTimeOption).map(([key, value]) => ({ label: value, value: key })),
			action: (key: string, value: string) => partialUpdate(key, value),
		},
	];

	return (
		<Flex vertical gap={8} className={styles.content}>
			<Typography.Title level={5} style={{ margin: 0 }}>
				{t('Уведомления')}
			</Typography.Title>
			<div className={styles.section}>
				<SwitchWithText
					subTitle={t(
						'Никакой рекламы и спама, только системные уведомления. Бот не будет удалять или размещать контент без вашего ведома',
					)}
					onSwitchChange={(val: boolean) => partialUpdate('bot_allow_messages', val)}
					isChecked={!!accountSettings?.bot_allow_messages}>
					{t('Разрешить получать сообщения от бота')}
				</SwitchWithText>
			</div>
			<Flex vertical gap={8} className={styles.section}>
				<SwitchWithText
					onSwitchChange={(val: boolean) => partialUpdate('bot_allow_send_post', val)}
					isChecked={!!accountSettings?.bot_allow_send_post}>
					{t('Присылать пост в бота')}
				</SwitchWithText>
				<dl className={styles.table}>
					{botPostArray.map((item) => (
						<ProfileItem item={item} key={item.key} isDisabled={item.isDisabled} />
					))}
				</dl>
			</Flex>
			<div className={styles.section}>
				<SwitchWithText
					onSwitchChange={(val: boolean) => partialUpdate('bot_notify_on_task_completion', val)}
					isChecked={!!accountSettings?.bot_notify_on_task_completion}>
					{t('Уведомлять о выполнении заданий')}
				</SwitchWithText>
			</div>
		</Flex>
	);
};
