import { FC, HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useParams } from 'react-router-dom';

import cn from 'classnames';

import { useAdvcampaignsRetrieveQuery } from 'entities/Brand';
import { EditPostPageState, PostForm } from 'entities/Post';
import { useBackButton } from 'shared/hooks';
import { EMainRoutes } from 'shared/typings';
import { OverlayLoader, Page, PageTitle } from 'shared/ui';

interface IEditPostProps extends HTMLAttributes<HTMLDivElement> {}

export const EditPost: FC<IEditPostProps> = ({ className, ...props }) => {
	const { t } = useTranslation();

	const { advCampaignId } = useParams<{ advCampaignId: string }>();
	const { data: advCampaign, isLoading } = useAdvcampaignsRetrieveQuery(advCampaignId || '', { skip: !advCampaignId });
	const [pageState, setPageState] = useState<EditPostPageState>(EditPostPageState.PUBLISHING_SETTINGS);

	useBackButton(
		advCampaign?.brand.uuid ? `/${EMainRoutes.BRAND}/${advCampaign?.brand.uuid}` : `/${EMainRoutes.CATALOG}`,
	);

	const contentMap = {
		[EditPostPageState.POST_EDITOR]: {
			title: t('Редактор поста'),
			subTitle: t('Создайте новый текст, или добавьте свою иллюстрацию'),
		},
		[EditPostPageState.PUBLISHING_SETTINGS]: {
			title: t('Настройки публикации'),
			subTitle: t('Выберите канал и время публикации'),
		},
	};

	return (
		<Page {...props} className={cn(className)}>
			{isLoading && <OverlayLoader />}
			<PageTitle subtitle={contentMap[pageState].subTitle}>{contentMap[pageState].title}</PageTitle>
			{!!advCampaign && <PostForm advCampaign={advCampaign} pageState={pageState} setPageState={setPageState} />}
		</Page>
	);
};

export default EditPost;
